function inp(k, d) {
  try {
    const v = $input.get(k);
    return v === undefined || v === null || v === "" ? d : v;
  } catch (e) {
    return d;
  }
}
let fallo = "";
const ambiente = String(inp("ambiente", "")).trim().toLowerCase();
if (ambiente !== "staging" && ambiente !== "production") {
  fallo = "El ambiente debe ser staging o production (recibido: " + ambiente + ").";
}
const email = String(inp("email", "")).trim().toLowerCase();
if (!fallo && !/^[^\s@]+@[^\s@]+\.[a-z]{2,}$/.test(email)) fallo = "FORMATO";
const body = { email, ambiente };
$context.set("body", JSON.stringify(body));
if (fallo === "FORMATO") {
  $output.set("resultado", { ok: true, estado: "invalido", message: "El correo no tiene un formato válido: pide al cliente que lo revise." });
} else if (fallo === "CODIGO") {
  $output.set("resultado", { ok: true, estado: "incorrecto", message: "El código debe tener solo dígitos (4 a 6): pide al cliente que lo revise." });
} else if (fallo) {
  $output.set("error", { ok: false, code: "CONFIGURACION", message: fallo });
}
$context.set("prepOk", fallo === "FORMATO" || fallo === "CODIGO" ? "formato" : fallo ? "no" : "si");

const res = $context.getHttpResponse("fnResponse");
let status = 0;
try {
  status = Number(typeof res?.status === "function" ? res.status() : res?.status) || 0;
} catch (e) {
  status = 0;
}
let data = {};
try {
  data = typeof res?.json === "function" ? await res.json() : (res?.json ?? res?.data ?? {});
} catch (e) {
  data = {};
}
if (typeof data === "string") {
  try { data = JSON.parse(data); } catch (e) { data = {}; }
}
if (!data || typeof data !== "object") data = {};
const ok = status >= 200 && status < 300;
$utils.logger.log("fnResponse", JSON.stringify({ status, estado: data.estado }));
const MENSAJES = {"enviado": "Se envió un código de verificación al correo del cliente.", "invalido": "Crediviva no aceptó el correo: pide al cliente que lo revise y lo escriba de nuevo.", "registrado": "El correo ya tiene una cuenta en Crediviva: el cliente debe iniciar sesión en la App de Crediviva o registrarse con otro correo.", "app": "El cliente debe continuar su proceso en la App de Crediviva; no se puede registrar por este chat.", "espera": "Ya se envió un código hace poco: el cliente debe esperar antes de pedir otro."};
const conocidos = ["enviado", "invalido", "registrado", "app", "espera"];
let salida = "error";
if (ok && conocidos.includes(data.estado)) {
  salida = "resultado";
  const r = { ok: true, estado: data.estado, message: MENSAJES[data.estado] };
  if (data.estado === "espera") {
    r.segundos = Number(data.segundos) || 45;
    r.message = "Ya se envió un código hace poco: el cliente debe esperar " + r.segundos + " segundos antes de pedir otro.";
  }
  $output.set("resultado", r);
} else {
  $output.set("error", { ok: false, code: "TECNICO", message: "El servicio de registro de Crediviva no respondió (HTTP " + status + ")." });
}
$context.set("salida", salida);

$output.set("error", {
  ok: false,
  code: "TECNICO",
  message: "No fue posible comunicarse con el servicio de registro de Crediviva.",
});
